// EPC engine for the app.
//
// getEPC(checkers) returns the effective pip count (8.1667 x expected rolls to bear off) of a
// one-sided position, in one of three ways:
//
//   kind "exact"     every checker is on the 7 point or lower. Looked up in the precomputed table
//                    (generated by epc_gen_fast.py), exact to 0.01.
//   kind "approx"    at least one checker is outside the 7 point ("straggler"). Computed on the fly:
//                    stragglers are brought home rear-first, and as soon as they are all in, the
//                    exact table takes over (including the rest of that roll). Every roll is
//                    averaged exactly (all 21 rolls, both dice orders), so the only approximation
//                    is the straggler-moving policy. Slightly high: about 0.1-0.2 pips on
//                    average and up to ~1 pip in awkward positions in testing.
//   kind "estimate"  too many stragglers for the exact averaging to finish quickly, so the same
//                    policy is simulated (fixed random seed, so the answer is repeatable).
//                    Typically within ~0.2 pips of the "approx" value.
//
// Position format: array of 24 counts, index 0 = 1 point ... index 23 = 24 point.
// Checkers not on the board are borne off (at most 15 on the board).

import EPC_TABLE_BASE64 from './epcTable';

const POINTS = 7;                 // table covers the 7 point .. 1 point
const MAX_CHECKERS = 15;
const ROLL_PIPS = 294 / 36;
const FIRST_STRAGGLER_POINT = POINTS + 1;

// Tuning: how much work we do before switching strategy (keeps the UI responsive)
const MAX_POLICY_STATES = 3000;   // exact averaging budget, in distinct (stragglers, home) states
const SIMULATIONS = 20000;        // paths for the "estimate" fallback

const ROLLS = [];                 // [dice, weight]; weights sum to 36
for (let i = 1; i <= 6; i++) {
  for (let j = i; j <= 6; j++) {
    ROLLS.push(i === j ? [[i, i, i, i], 1] : [[j, i], 2]);
  }
}

// ---------------------------------------------------------------- table access
const BINOM = (() => {
  const size = MAX_CHECKERS + POINTS + 1;
  const c = Array.from({ length: size }, () => new Array(size).fill(0));
  for (let n = 0; n < size; n++) {
    c[n][0] = 1;
    for (let k = 1; k <= n; k++) c[n][k] = c[n - 1][k - 1] + (k <= n - 1 ? c[n - 1][k] : 0);
  }
  return c;
})();

function decodeBase64ToUint16(b64) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup = new Int16Array(128).fill(-1);
  for (let i = 0; i < chars.length; i++) lookup[chars.charCodeAt(i)] = i;

  const clean = b64.replace(/=+$/, '');
  const bytes = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let acc = 0, bits = 0, out = 0;
  for (let i = 0; i < clean.length; i++) {
    acc = (acc << 6) | lookup[clean.charCodeAt(i)];
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes[out++] = (acc >> bits) & 0xff;
    }
  }
  const values = new Uint16Array(bytes.length >> 1);
  for (let i = 0; i < values.length; i++) values[i] = bytes[2 * i] | (bytes[2 * i + 1] << 8);
  return values;
}

let table = null;
function getTable() {
  if (!table) table = decodeBase64ToUint16(EPC_TABLE_BASE64);
  return table;
}

// Index of a 7-point position (p[0] = 7 point ... p[6] = 1 point): combinatorial number system
function rank(p) {
  let pos = -1, r = 0;
  for (let k = 0; k < POINTS; k++) {
    pos += p[k] + 1;
    r += BINOM[pos][k + 1];
  }
  return r;
}

const tableEPC = (home) => getTable()[rank(home)] / 100;

const isEmpty = (p) => {
  for (let i = 0; i < p.length; i++) if (p[i]) return false;
  return true;
};

const homeKey = (p) => {
  let k = 0;
  for (let i = 0; i < POINTS; i++) k = k * 16 + p[i];
  return k;
};

// ---------------------------------------------------------------- bear-off moves in the table region
const transCache = new Map();

// Positions reachable by playing one die. Rules: no bearing off while a checker is on the 7 point;
// a die larger than every checker's distance bears off the rearmost checker.
function transitions(home, die) {
  const key = homeKey(home) * 8 + die;
  let res = transCache.get(key);
  if (res) return res;

  const last = home[0] ? POINTS - 1 - die : POINTS - die;
  const seen = new Set();
  res = [];
  const add = (q) => {
    const k = homeKey(q);
    if (!seen.has(k)) { seen.add(k); res.push(q); }
  };
  for (let i = 0; i <= last; i++) {
    if (home[i]) {
      const q = home.slice();
      q[i]--;
      if (i + die < POINTS) q[i + die]++;
      add(q);
    }
  }
  if (res.length === 0) {
    const q = home.slice();
    for (let i = 0; i < POINTS; i++) if (q[i]) { q[i]--; break; }
    add(q);
  }
  transCache.set(key, res);
  return res;
}

// Best EPC reachable after playing `dice` (in this order) from a table position
const homeBestCache = new Map();
function homeBest(home, dice, from) {
  if (isEmpty(home)) return 0;
  if (from >= dice.length) return tableEPC(home);
  let code = '';
  for (let i = from; i < dice.length; i++) code += dice[i];
  const key = homeKey(home) + '|' + code;
  let v = homeBestCache.get(key);
  if (v === undefined) {
    v = Infinity;
    for (const q of transitions(home, dice[from])) v = Math.min(v, homeBest(q, dice, from + 1));
    homeBestCache.set(key, v);
  }
  return v;
}

// ---------------------------------------------------------------- stragglers
// A state is (S, H): S = straggler points, sorted high to low (all >= 8); H = table position.
class BudgetExceeded extends Error {}

function afterRoll(S, H, dice, memo) {
  S = S.slice();
  for (let k = 0; k < dice.length; k++) {
    if (S.length === 0) return homeBest(H, dice, k);
    const to = S.shift() - dice[k];            // the rearmost straggler plays every die
    if (to >= FIRST_STRAGGLER_POINT) {
      S.push(to);
      S.sort((a, b) => b - a);
    } else {
      H = H.slice();
      H[POINTS - to]++;
    }
  }
  return stateValue(S, H, memo);
}

function stateValue(S, H, memo) {
  if (S.length === 0) return tableEPC(H);
  const key = S.join(',') + '|' + homeKey(H);
  let v = memo.values.get(key);
  if (v !== undefined) return v;
  if (memo.values.size >= MAX_POLICY_STATES) throw new BudgetExceeded();

  let total = 0;
  for (const [dice, weight] of ROLLS) {
    let best = afterRoll(S, H, dice, memo);
    if (dice.length === 2) best = Math.min(best, afterRoll(S, H, [dice[1], dice[0]], memo));
    total += weight * (best + ROLL_PIPS);
  }
  v = total / 36;
  memo.values.set(key, v);
  return v;
}

// Seeded generator so the "estimate" fallback gives the same answer every time
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function simulate(S0, H0, seed) {
  const rand = mulberry32(seed);
  let sum = 0;
  for (let n = 0; n < SIMULATIONS; n++) {
    let S = S0.slice(), H = H0.slice(), acc = 0, done = false;
    while (!done) {
      acc += ROLL_PIPS;
      const a = 1 + Math.floor(rand() * 6), b = 1 + Math.floor(rand() * 6);
      const dice = a === b ? [a, a, a, a] : [Math.max(a, b), Math.min(a, b)];
      for (let k = 0; k < dice.length; k++) {
        if (S.length === 0) { acc += homeBest(H, dice, k); done = true; break; }
        const to = S.shift() - dice[k];
        if (to >= FIRST_STRAGGLER_POINT) { S.push(to); S.sort((x, y) => y - x); }
        else { H = H.slice(); H[POINTS - to]++; }
      }
      if (!done && S.length === 0) { acc += tableEPC(H); done = true; }
    }
    sum += acc;
  }
  return sum / SIMULATIONS;
}

// ---------------------------------------------------------------- public API
/**
 * @param {number[]} checkers 24 counts, index 0 = 1 point ... index 23 = 24 point
 * @returns {{epc: number, kind: 'exact'|'approx'|'estimate', stragglers: number} | null}
 *          null if the position is invalid (more than 15 checkers).
 */
export function getEPC(checkers) {
  const home = [];                                   // 7 point .. 1 point
  for (let pt = POINTS; pt >= 1; pt--) home.push(checkers[pt - 1] || 0);
  const stragglers = [];
  for (let pt = 24; pt >= FIRST_STRAGGLER_POINT; pt--) {
    for (let c = 0; c < (checkers[pt - 1] || 0); c++) stragglers.push(pt);
  }

  if (home.reduce((a, b) => a + b, 0) + stragglers.length > MAX_CHECKERS) return null;

  if (stragglers.length === 0) {
    return { epc: tableEPC(home), kind: 'exact', stragglers: 0 };
  }

  try {
    const value = stateValue(stragglers, home, { values: new Map() });
    return { epc: value, kind: 'approx', stragglers: stragglers.length };
  } catch (e) {
    if (!(e instanceof BudgetExceeded)) throw e;
    const seed = stragglers.reduce((s, p) => (s * 31 + p) >>> 0, homeKey(home) >>> 0);
    return { epc: simulate(stragglers, home, seed), kind: 'estimate', stragglers: stragglers.length };
  }
}

// True if the position can be answered from the table alone
export const isTablePosition = (checkers) => {
  for (let pt = FIRST_STRAGGLER_POINT; pt <= 24; pt++) if (checkers[pt - 1]) return false;
  return true;
};

// ---------------------------------------------------------------- helpers for the position screens
/** True if no checker is beyond the 6 point (the JSON file only covers these positions) */
export const isWithinSixPoint = (checkers) => {
  for (let pt = 7; pt <= 24; pt++) if (checkers[pt - 1]) return false;
  return true;
};

/**
 * Key into epc_positions.json: checkers on the 6 point down to the 1 point, then the number borne
 * off, as 7 hex digits. Only meaningful when isWithinSixPoint(checkers).
 */
export function positionKey(checkers) {
  const borneOff = MAX_CHECKERS - checkers.reduce((a, b) => a + b, 0);
  let key = '';
  for (let pt = 6; pt >= 1; pt--) key += (checkers[pt - 1] || 0).toString(16);
  return (key + borneOff.toString(16)).toUpperCase();
}
